  using(var dialog=(Form)Activator.CreateInstance(app.GetType("SaveProfileDialog"),true)) {dialog.Show();Application.DoEvents();using var bmp=new System.Drawing.Bitmap(dialog.Width,dialog.Height);dialog.DrawToBitmap(bmp,new System.Drawing.Rectangle(0,0,bmp.Width,bmp.Height));bmp.Save(Path.Combine(root,"profile-dialog.png"));dialog.Close();}
